WITH flattened AS (SELECT id, service, host, log_ts, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT id, service, host, log_ts, status_code, key, attr_value, RANK() OVER (PARTITION BY MONTH(log_ts), key ORDER BY status_code DESC) AS status_code_rank, SUM(status_code) OVER (PARTITION BY host, key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS status_code_sum_15m, DENSE_RANK() OVER w_ordered AS status_code_dense_rank, ROW_NUMBER() OVER (PARTITION BY host ORDER BY status_code, id, key) AS event_seq, SUM(status_code) OVER w_hist AS host_sum_status_code FROM flattened WHERE log_ts >= '2023-09-26' WINDOW w_ordered AS (PARTITION BY host ORDER BY status_code DESC), w_hist AS (PARTITION BY host);
